type View = 'dashboard' | 'map' | 'scanner' | 'issues' | 'reports' | 'assistant';
type Status = 'good' | 'warning' | 'critical';
type Severity = 'low' | 'medium' | 'high';

type Building = {
  id: string;
  name: string;
  short: string;
  type: string;
  energy: number;
  water: number;
  occupancy: number;
  score: number;
  status: Status;
  x: number;
  y: number;
  color: string;
};

type Issue = {
  id: number;
  building: string;
  type: 'Energy' | 'Water' | 'Waste' | 'HVAC';
  title: string;
  detail: string;
  recommendation: string;
  severity: Severity;
  time: string;
  status: 'Open' | 'Resolved';
};

