const initialIssues: Issue[] = [
  { id: 1, building: 'Girls Hostel Block B', type: 'Water', title: 'Water flow detected during zero occupancy', detail: '48.2 L/min at 02:14 AM with no registered occupants.', recommendation: 'Inspect basement plumbing within 24 hours. Estimated savings: 1,200 L/day.', severity: 'high', time: '12 min ago', status: 'Open' },
  { id: 2, building: 'Canteen', type: 'Waste', title: 'Bin approaching overflow capacity', detail: 'Computer vision estimate: 87% full, mixed waste detected.', recommendation: 'Schedule collection before the evening rush. Reposition organic waste bin closer to prep area.', severity: 'medium', time: '28 min ago', status: 'Open' },
  { id: 3, building: 'Boys Hostel Block A', type: 'Energy', title: 'Unusual evening energy spike', detail: 'Consumption is 34% above the 7-day baseline after 11 PM.', recommendation: 'Check common-room HVAC timers and water heaters on floors 2–4.', severity: 'medium', time: '1 hr ago', status: 'Open' },
  { id: 4, building: 'Main Academic Block', type: 'HVAC', title: 'HVAC running in low-occupancy wing', detail: 'North wing drawing 18.4 kWh with only 3 occupants.', recommendation: 'Enable occupancy-based HVAC scheduling for the north wing.', severity: 'low', time: '2 hrs ago', status: 'Open' },
  { id: 5, building: 'Central Library', type: 'Energy', title: 'Lighting efficiency improved', detail: 'Energy use is 12% below baseline after lighting schedule update.', recommendation: 'Replicate the daylight harvesting schedule across Academic Block.', severity: 'low', time: 'Yesterday', status: 'Resolved' },
  { id: 6, building: 'Sports Complex', type: 'Water', title: 'Irrigation cycle optimized', detail: 'Morning irrigation reduced by 420 L after weather-aware schedule.', recommendation: 'Maintain current schedule and monitor turf moisture weekly.', severity: 'low', time: 'Yesterday', status: 'Resolved' },
];

const trendData = [
  { day: 'Mon', energy: 1120, water: 720, waste: 64 },
  { day: 'Tue', energy: 1080, water: 680, waste: 59 },
  { day: 'Wed', energy: 1240, water: 790, waste: 73 },
  { day: 'Thu', energy: 1160, water: 710, waste: 61 },
  { day: 'Fri', energy: 1050, water: 650, waste: 56 },
  { day: 'Sat', energy: 880, water: 540, waste: 42 },
  { day: 'Sun', energy: 810, water: 490, waste: 38 },
];

const navItems: { id: View; label: string; icon: typeof Gauge }[] = [
  { id: 'dashboard', label: 'Overview', icon: Gauge },
  { id: 'map', label: 'Campus map', icon: Map },
  { id: 'scanner', label: 'Waste scanner', icon: Recycle },
  { id: 'issues', label: 'Issues & alerts', icon: Bell },
  { id: 'reports', label: 'Analytics & reports', icon: BarChart3 },
  { id: 'assistant', label: 'Ask EcoCampus', icon: Bot },
];

const statusStyles: Record<Status, { label: string; className: string; dot: string }> = {
  good: { label: 'Good', className: 'bg-emerald-50 text-emerald-700 dark:bg-emerald-500/15 dark:text-emerald-400', dot: 'bg-emerald-500' },
  warning: { label: 'Warning', className: 'bg-amber-50 text-amber-700 dark:bg-amber-500/15 dark:text-amber-400', dot: 'bg-amber-500' },
  critical: { label: 'Critical', className: 'bg-red-50 text-red-700 dark:bg-red-500/15 dark:text-red-400', dot: 'bg-red-500' },
};

function StatusBadge({ status }: { status: Status }) {
  const style = statusStyles[status];
  return <span className={`inline-flex items-center gap-1.5 rounded-full px-2.5 py-1 text-[11px] font-semibold ${style.className}`}><span className={`h-1.5 w-1.5 rounded-full ${style.dot}`} />{style.label}</span>;
}

function SectionTitle({ eyebrow, title, detail, action }: { eyebrow?: string; title: string; detail?: string; action?: ReactNode }) {
  return <div className="mb-6 flex items-end justify-between gap-4"><div><p className="mb-1 text-[11px] font-bold uppercase tracking-[0.18em] text-primary">{eyebrow}</p><h1 className="font-display text-2xl font-bold tracking-tight sm:text-3xl">{title}</h1>{detail && <p className="mt-1.5 text-sm text-muted-foreground">{detail}</p>}</div>{action}</div>;
}

function StatCard({ icon: Icon, label, value, detail, trend, tone = 'green' }: { icon: typeof Zap; label: string; value: string; detail: string; trend?: string; tone?: 'green' | 'blue' | 'amber' | 'red' }) {
  const tones = { green: 'bg-emerald-50 text-emerald-600 dark:bg-emerald-500/15 dark:text-emerald-400', blue: 'bg-sky-50 text-sky-600 dark:bg-sky-500/15 dark:text-sky-400', amber: 'bg-amber-50 text-amber-600 dark:bg-amber-500/15 dark:text-amber-400', red: 'bg-red-50 text-red-600 dark:bg-red-500/15 dark:text-red-400' };
  return <div className="group rounded-2xl border bg-card p-5 shadow-sm transition-all hover:-translate-y-0.5 hover:shadow-md"><div className="flex items-start justify-between"><div className={`flex h-10 w-10 items-center justify-center rounded-xl ${tones[tone]}`}><Icon className="h-5 w-5" /></div>{trend && <span className="flex items-center gap-1 text-xs font-semibold text-emerald-600"><TrendingDown className="h-3.5 w-3.5" />{trend}</span>}</div><p className="mt-5 text-sm text-muted-foreground">{label}</p><p className="mt-1 font-display text-2xl font-bold tracking-tight">{value}</p><p className="mt-1 text-xs text-muted-foreground">{detail}</p></div>;
}

function ScoreGauge({ score }: { score: number }) {
  const radius = 70;
  const circumference = 2 * Math.PI * radius;
  const offset = circumference - (score / 100) * circumference;
  return <div className="relative h-48 w-48"><svg className="h-full w-full -rotate-90" viewBox="0 0 180 180"><circle cx="90" cy="90" r={radius} fill="none" stroke="currentColor" strokeWidth="12" className="text-muted/70" /><circle cx="90" cy="90" r={radius} fill="none" stroke="currentColor" strokeWidth="12" strokeLinecap="round" strokeDasharray={circumference} strokeDashoffset={offset} className="text-primary transition-all duration-1000 ease-out" /></svg><div className="absolute inset-0 flex flex-col items-center justify-center"><span className="font-display text-5xl font-bold tracking-tight">{score}</span><span className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">out of 100</span></div></div>;
}

function AlertsPanel({ issues, onResolve, compact = false }: { issues: Issue[]; onResolve: (id: number) => void; compact?: boolean }) {
  const active = issues.filter((issue) => issue.status === 'Open').slice(0, compact ? 4 : 20);
  return <div className="rounded-2xl border bg-card shadow-sm"><div className="flex items-center justify-between border-b px-5 py-4"><div><h2 className="font-display font-bold">Live alerts</h2><p className="mt-0.5 text-xs text-muted-foreground">{active.length} requiring attention</p></div><span className="relative flex h-8 w-8 items-center justify-center rounded-lg bg-red-50 text-red-500 dark:bg-red-500/15"><Bell className="h-4 w-4" /><span className="absolute -right-0.5 -top-0.5 h-2 w-2 rounded-full bg-red-500 ring-2 ring-card" /></span></div><div className={`divide-y ${compact ? '' : 'max-h-[580px] overflow-y-auto scrollbar-thin'}`}>{active.map((issue) => <div key={issue.id} className="group px-5 py-4 transition-colors hover:bg-muted/30"><div className="flex gap-3"><div className={`mt-1 h-2 w-2 shrink-0 rounded-full ${issue.severity === 'high' ? 'bg-red-500' : issue.severity === 'medium' ? 'bg-amber-500' : 'bg-sky-500'}`} /><div className="min-w-0 flex-1"><div className="flex items-start justify-between gap-2"><p className="text-sm font-semibold leading-snug">{issue.title}</p><span className="shrink-0 text-[10px] text-muted-foreground">{issue.time}</span></div><p className="mt-1 text-xs text-muted-foreground">{issue.building} · {issue.type}</p><button onClick={() => onResolve(issue.id)} className="mt-2 text-[11px] font-semibold text-primary opacity-0 transition-opacity hover:underline group-hover:opacity-100">Mark resolved</button></div></div></div>)}</div>{active.length === 0 && <div className="p-8 text-center text-sm text-muted-foreground"><ShieldCheck className="mx-auto mb-2 h-8 w-8 text-emerald-500" />All clear for now.</div>}</div>;
}

function CampusMap({ buildings, onSelect }: { buildings: Building[]; onSelect: (building: Building) => void }) {
  return <div className="relative min-h-[460px] overflow-hidden rounded-2xl border bg-[#e9f4f0] shadow-sm dark:bg-slate-900/80"><div className="absolute inset-0 opacity-50 dark:opacity-20" style={{ backgroundImage: 'linear-gradient(#b7d8cd 1px, transparent 1px), linear-gradient(90deg, #b7d8cd 1px, transparent 1px)', backgroundSize: '32px 32px' }} /><div className="absolute left-[7%] top-[48%] h-4 w-[86%] -rotate-12 rounded-full bg-white/80 shadow-sm dark:bg-slate-800/80" /><div className="absolute left-[46%] top-[4%] h-[92%] w-4 rotate-[16deg] rounded-full bg-white/80 shadow-sm dark:bg-slate-800/80" /><div className="absolute left-[15%] top-[45%] h-28 w-28 rounded-full border-8 border-white/70 bg-emerald-200/60 dark:border-slate-800/80 dark:bg-emerald-900/30" /><div className="absolute right-[8%] top-[42%] h-36 w-36 rounded-full border-8 border-white/70 bg-teal-200/60 dark:border-slate-800/80 dark:bg-teal-900/30" /><div className="absolute left-5 top-5 flex items-center gap-2 rounded-lg border border-white/80 bg-white/80 px-3 py-2 text-xs font-medium shadow-sm backdrop-blur dark:border-slate-700 dark:bg-slate-900/80"><Map className="h-3.5 w-3.5 text-primary" />Live campus twin <span className="ml-1 h-1.5 w-1.5 animate-pulse rounded-full bg-emerald-500" /></div>{buildings.map((building) => { const status = statusStyles[building.status]; return <button key={building.id} onClick={() => onSelect(building)} className="group absolute -translate-x-1/2 -translate-y-1/2 text-left transition-transform hover:z-10 hover:scale-105" style={{ left: `${building.x}%`, top: `${building.y}%` }}><span className={`absolute -inset-2 rounded-2xl ${building.status !== 'good' ? 'animate-pulse-ring' : ''} ${status.dot} opacity-20`} /><span className="relative block min-w-[104px] rounded-xl border border-white/80 bg-white/95 p-2.5 shadow-md backdrop-blur transition-shadow group-hover:shadow-xl dark:border-slate-700 dark:bg-slate-800/95"><span className="flex items-center justify-between gap-2"><span className="flex h-7 w-7 items-center justify-center rounded-lg" style={{ backgroundColor: `${building.color}20`, color: building.color }}><Building2 className="h-3.5 w-3.5" /></span><span className={`h-2 w-2 rounded-full ${status.dot}`} /></span><span className="mt-2 block text-[11px] font-bold text-slate-800 dark:text-white">{building.short}</span><span className="mt-0.5 block text-[10px] text-slate-500 dark:text-slate-400">Score {building.score}</span></span></button>; })}</div>;
}

function MiniChart({ dataKey, color, data = trendData }: { dataKey: string; color: string; data?: typeof trendData }) {
  return <ResponsiveContainer width="100%" height="100%"><AreaChart data={data}><defs><linearGradient id={`fill-${dataKey}`} x1="0" y1="0" x2="0" y2="1"><stop offset="5%" stopColor={color} stopOpacity={0.25} /><stop offset="95%" stopColor={color} stopOpacity={0} /></linearGradient></defs><XAxis dataKey="day" hide /><YAxis hide domain={['dataMin - 100', 'dataMax + 100']} /><Tooltip contentStyle={{ borderRadius: 12, border: '1px solid hsl(var(--border))', background: 'hsl(var(--card))', fontSize: 11 }} /><Area type="monotone" dataKey={dataKey} stroke={color} strokeWidth={2.5} fill={`url(#fill-${dataKey})`} animationDuration={900} /></AreaChart></ResponsiveContainer>;
}

function Dashboard({ buildings, issues, onResolve, onSelect }: { buildings: Building[]; issues: Issue[]; onResolve: (id: number) => void; onSelect: (building: Building) => void }) {
  const score = Math.round(buildings.reduce((sum, building) => sum + building.score, 0) / buildings.length);
  return <div className="space-y-6"><SectionTitle eyebrow="Campus intelligence · Live" title="Good morning, Alex" detail="Here’s what’s happening across your campus right now." action={<button className="hidden items-center gap-2 rounded-xl bg-primary px-4 py-2.5 text-sm font-semibold text-primary-foreground shadow-sm transition hover:bg-primary/90 sm:flex"><Sparkles className="h-4 w-4" />Generate insight</button>} /><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><div className="flex items-center gap-5 rounded-2xl border bg-card p-5 shadow-sm sm:col-span-2 xl:col-span-1"><ScoreGauge score={score} /><div><p className="text-sm font-semibold">Campus score</p><p className="mt-1 text-xs leading-relaxed text-muted-foreground">Top 18% of comparable campuses</p><div className="mt-3 flex items-center gap-1.5 text-xs font-semibold text-emerald-600"><ArrowUpRight className="h-3.5 w-3.5" />8.4% this month</div></div></div><StatCard icon={Bell} label="Active alerts" value={String(issues.filter((issue) => issue.status === 'Open').length).padStart(2, '0')} detail="3 high priority" tone="red" /><StatCard icon={Zap} label="Energy savings potential" value="1,284 kWh" detail="This month" trend="14.2%" tone="blue" /><StatCard icon={Droplets} label="Water savings potential" value="8,640 L" detail="Per week" trend="22.8%" tone="green" /></div><div className="grid gap-6 xl:grid-cols-[minmax(0,1.65fr)_minmax(330px,0.85fr)]"><div className="space-y-6"><div className="flex items-center justify-between"><div><h2 className="font-display text-lg font-bold">Campus digital twin</h2><p className="mt-1 text-xs text-muted-foreground">Click a zone to inspect live performance</p></div><button onClick={() => onSelect(buildings[0])} className="flex items-center gap-1 text-xs font-semibold text-primary hover:underline">View details <ChevronRight className="h-3.5 w-3.5" /></button></div><CampusMap buildings={buildings} onSelect={onSelect} /><div className="grid gap-4 sm:grid-cols-3"><div className="rounded-2xl border bg-card p-4 shadow-sm"><div className="mb-3 flex items-center justify-between"><span className="text-sm font-semibold">Energy use</span><Zap className="h-4 w-4 text-sky-500" /></div><p className="font-display text-xl font-bold">1,320 <span className="text-xs font-medium text-muted-foreground">kWh</span></p><div className="mt-3 h-12"><MiniChart dataKey="energy" color="#0ea5e9" /></div></div><div className="rounded-2xl border bg-card p-4 shadow-sm"><div className="mb-3 flex items-center justify-between"><span className="text-sm font-semibold">Water flow</span><Waves className="h-4 w-4 text-emerald-500" /></div><p className="font-display text-xl font-bold">842 <span className="text-xs font-medium text-muted-foreground">L/min</span></p><div className="mt-3 h-12"><MiniChart dataKey="water" color="#10b981" /></div></div><div className="rounded-2xl border bg-card p-4 shadow-sm"><div className="mb-3 flex items-center justify-between"><span className="text-sm font-semibold">Waste diverted</span><Recycle className="h-4 w-4 text-amber-500" /></div><p className="font-display text-xl font-bold">68.4 <span className="text-xs font-medium text-muted-foreground">%</span></p><div className="mt-3 h-12"><MiniChart dataKey="waste" color="#f59e0b" /></div></div></div></div><AlertsPanel issues={issues} onResolve={onResolve} compact /></div></div>;
}

function BuildingDetail({ building, issues, onBack, onScan }: { building: Building; issues: Issue[]; onBack: () => void; onScan: () => void }) {
  const [range, setRange] = useState('24h');
  const detailData = trendData.map((item, index) => ({ ...item, usage: Math.round(building.energy * (0.72 + index * 0.035) + (index % 2) * 30), flow: Math.round(building.water * (0.78 + index * 0.03)) }));
  const buildingIssues = issues.filter((issue) => issue.building === building.name && issue.status === 'Open');
  return <div className="space-y-6"><button onClick={onBack} className="flex items-center gap-1.5 text-sm font-semibold text-muted-foreground transition hover:text-foreground">← Back to overview</button><SectionTitle eyebrow={building.type} title={building.name} detail="Live building performance and detected conditions." action={<StatusBadge status={building.status} />} /><div className="grid gap-4 sm:grid-cols-3"><StatCard icon={Zap} label="Current energy" value={`${building.energy} kWh`} detail="12% below baseline" trend="12%" tone="blue" /><StatCard icon={Droplets} label="Water flow" value={`${building.water} L/min`} detail="Last updated just now" tone={building.status === 'critical' ? 'red' : 'green'} /><StatCard icon={Users} label="Occupancy" value={`${building.occupancy}%`} detail="Estimated from access data" tone="amber" /></div><div className="grid gap-6 lg:grid-cols-[minmax(0,1.55fr)_minmax(300px,0.75fr)]"><div className="rounded-2xl border bg-card p-5 shadow-sm"><div className="flex items-center justify-between"><div><h2 className="font-display text-lg font-bold">Resource usage</h2><p className="mt-1 text-xs text-muted-foreground">Energy and water consumption trend</p></div><div className="flex rounded-lg bg-muted p-1 text-xs font-semibold"><button onClick={() => setRange('24h')} className={`rounded-md px-3 py-1.5 transition ${range === '24h' ? 'bg-card shadow-sm' : 'text-muted-foreground'}`}>24h</button><button onClick={() => setRange('7d')} className={`rounded-md px-3 py-1.5 transition ${range === '7d' ? 'bg-card shadow-sm' : 'text-muted-foreground'}`}>7 days</button></div></div><div className="mt-6 h-[290px]"><ResponsiveContainer width="100%" height="100%"><LineChart data={detailData}><CartesianGrid strokeDasharray="3 3" stroke="hsl(var(--border))" vertical={false} /><XAxis dataKey="day" tick={{ fontSize: 11 }} tickLine={false} axisLine={false} /><YAxis tick={{ fontSize: 11 }} tickLine={false} axisLine={false} /><Tooltip contentStyle={{ borderRadius: 12, border: '1px solid hsl(var(--border))', background: 'hsl(var(--card))', fontSize: 12 }} /><Line type="monotone" dataKey="usage" name="Energy (kWh)" stroke="#0ea5e9" strokeWidth={3} dot={false} /><Line type="monotone" dataKey="flow" name="Water (L/min)" stroke="#10b981" strokeWidth={3} dot={false} /></LineChart></ResponsiveContainer></div><div className="mt-3 flex gap-5 text-xs text-muted-foreground"><span className="flex items-center gap-2"><span className="h-2 w-2 rounded-full bg-sky-500" />Energy</span><span className="flex items-center gap-2"><span className="h-2 w-2 rounded-full bg-emerald-500" />Water flow</span></div></div><div className="rounded-2xl border bg-card p-5 shadow-sm"><div className="flex items-center justify-between"><div><h2 className="font-display text-lg font-bold">Building health</h2><p className="mt-1 text-xs text-muted-foreground">Sustainability signals</p></div><Activity className="h-5 w-5 text-primary" /></div><div className="mt-6 flex items-center justify-center"><ScoreGauge score={building.score} /></div><div className="mt-3 space-y-3 border-t pt-4"><div className="flex items-center justify-between text-sm"><span className="text-muted-foreground">Energy efficiency</span><span className="font-semibold text-emerald-600">Excellent</span></div><div className="flex items-center justify-between text-sm"><span className="text-muted-foreground">Water efficiency</span><span className={`font-semibold ${building.status === 'critical' ? 'text-red-500' : 'text-amber-500'}`}>{building.status === 'critical' ? 'Needs review' : 'Good'}</span></div></div></div></div><div className="grid gap-6 lg:grid-cols-[minmax(0,1fr)_320px]"><div className="rounded-2xl border bg-card p-5 shadow-sm"><div className="mb-4 flex items-center justify-between"><div><h2 className="font-display text-lg font-bold">Active issues</h2><p className="mt-1 text-xs text-muted-foreground">Conditions that need your attention</p></div><span className="rounded-full bg-muted px-2.5 py-1 text-xs font-semibold">{buildingIssues.length}</span></div>{buildingIssues.length ? <div className="space-y-3">{buildingIssues.map((issue) => <div key={issue.id} className="rounded-xl border bg-muted/30 p-4"><div className="flex items-start justify-between gap-3"><div><p className="text-sm font-semibold">{issue.title}</p><p className="mt-1 text-xs leading-relaxed text-muted-foreground">{issue.detail}</p></div><span className={`rounded-full px-2 py-1 text-[10px] font-bold uppercase ${issue.severity === 'high' ? 'bg-red-100 text-red-700 dark:bg-red-500/15 dark:text-red-400' : 'bg-amber-100 text-amber-700 dark:bg-amber-500/15 dark:text-amber-400'}`}>{issue.severity}</span></div></div>)}</div> : <div className="rounded-xl bg-emerald-50 p-5 text-sm text-emerald-700 dark:bg-emerald-500/10 dark:text-emerald-400"><Check className="mb-2 h-5 w-5" />No active issues in this building.</div>}</div><button onClick={onScan} className="flex min-h-[150px] flex-col items-center justify-center rounded-2xl border-2 border-dashed border-primary/30 bg-primary/[0.03] p-5 text-center transition hover:border-primary hover:bg-primary/[0.06]"><Recycle className="mb-3 h-8 w-8 text-primary" /><span className="text-sm font-bold">Run waste check</span><span className="mt-1 text-xs text-muted-foreground">Upload a bin image for AI analysis</span></button></div></div>;
}

function Scanner({ onLog }: { onLog: (issue: Issue) => void }) {
  const [scanning, setScanning] = useState(false);
  const [result, setResult] = useState<{ level: string; percent: number; risk: string; recommendation: string } | null>(null);
  const runScan = () => { setScanning(true); setResult(null); window.setTimeout(() => { setScanning(false); setResult({ level: 'Nearly full', percent: 87, risk: 'High overflow risk', recommendation: 'Schedule a collection before the evening rush. Move the organic waste container closer to the prep area and add a second 120L bin during peak hours.' }); }, 1400); };
  return <div className="space-y-6"><SectionTitle eyebrow="Computer vision" title="Waste scanner" detail="Turn a quick photo into an actionable waste-management decision." /><div className="grid gap-6 lg:grid-cols-[minmax(0,1.15fr)_minmax(300px,0.85fr)]"><div className="rounded-2xl border bg-card p-5 shadow-sm"><div className="mb-5 flex items-center justify-between"><div><h2 className="font-display text-lg font-bold">Scan a waste area</h2><p className="mt-1 text-xs text-muted-foreground">Our AI estimates fill level and overflow risk.</p></div><span className="flex items-center gap-1.5 rounded-full bg-emerald-50 px-2.5 py-1 text-[11px] font-semibold text-emerald-700 dark:bg-emerald-500/15 dark:text-emerald-400"><Sparkles className="h-3 w-3" />AI vision</span></div><button onClick={runScan} disabled={scanning} className="group flex min-h-[280px] w-full flex-col items-center justify-center rounded-2xl border-2 border-dashed border-primary/30 bg-gradient-to-b from-primary/[0.04] to-transparent transition hover:border-primary hover:bg-primary/[0.07] disabled:cursor-wait"><div className="flex h-16 w-16 items-center justify-center rounded-2xl bg-primary/10 text-primary transition group-hover:scale-105"><Upload className="h-7 w-7" /></div><span className="mt-4 text-sm font-bold">{scanning ? 'Analyzing image…' : 'Drop image here or click to upload'}</span><span className="mt-1 text-xs text-muted-foreground">PNG, JPG up to 10MB</span>{scanning && <div className="mt-5 h-1.5 w-48 overflow-hidden rounded-full bg-muted"><div className="h-full w-2/3 animate-pulse rounded-full bg-primary" /></div>}</button><div className="mt-4 flex items-center justify-between"><span className="text-xs text-muted-foreground">Quick demo samples</span><div className="flex gap-2"><button onClick={runScan} className="rounded-lg border px-3 py-1.5 text-[11px] font-semibold transition hover:border-primary hover:text-primary">Canteen bin</button><button onClick={runScan} className="rounded-lg border px-3 py-1.5 text-[11px] font-semibold transition hover:border-primary hover:text-primary">Hostel bin</button></div></div></div><div className="rounded-2xl border bg-card p-5 shadow-sm"><div className="flex items-center gap-3"><div className="flex h-10 w-10 items-center justify-center rounded-xl bg-sky-50 text-sky-600 dark:bg-sky-500/15 dark:text-sky-400"><Lightbulb className="h-5 w-5" /></div><div><h2 className="font-display font-bold">How it works</h2><p className="text-xs text-muted-foreground">A faster path from detection to action</p></div></div><div className="mt-6 space-y-5">{[['01', 'Upload a photo', 'Take a photo of any bin or waste area.'], ['02', 'AI classifies it', 'Fill level and overflow risk are detected automatically.'], ['03', 'Act before it matters', 'Get a practical recommendation your team can use.']].map(([num, title, text]) => <div key={num} className="flex gap-3"><span className="font-display text-sm font-bold text-primary">{num}</span><div><p className="text-sm font-semibold">{title}</p><p className="mt-0.5 text-xs leading-relaxed text-muted-foreground">{text}</p></div></div>)}</div></div></div>{result && <div className="animate-fade-in-up rounded-2xl border border-amber-200 bg-amber-50/70 p-5 shadow-sm dark:border-amber-500/30 dark:bg-amber-500/10"><div className="flex flex-col gap-5 sm:flex-row sm:items-start sm:justify-between"><div className="flex gap-4"><div className="flex h-12 w-12 shrink-0 items-center justify-center rounded-xl bg-amber-500 text-white"><AlertTriangle className="h-6 w-6" /></div><div><div className="flex flex-wrap items-center gap-2"><h2 className="font-display text-lg font-bold">Scan complete</h2><span className="rounded-full bg-red-100 px-2.5 py-1 text-[10px] font-bold uppercase text-red-700 dark:bg-red-500/20 dark:text-red-400">{result.risk}</span></div><p className="mt-1 text-sm text-amber-900/70 dark:text-amber-200/70">Canteen · Sample image analyzed</p></div></div><div className="text-left sm:text-right"><p className="text-3xl font-bold text-amber-700 dark:text-amber-400">{result.percent}%</p><p className="text-xs font-medium text-amber-900/60 dark:text-amber-200/60">{result.level}</p></div></div><div className="mt-5 grid gap-4 border-t border-amber-200/70 pt-4 sm:grid-cols-[1fr_auto] dark:border-amber-500/20"><div><p className="text-xs font-bold uppercase tracking-wider text-amber-800/70 dark:text-amber-200/70">AI recommendation</p><p className="mt-1.5 max-w-2xl text-sm leading-relaxed text-amber-950/80 dark:text-amber-100/80">{result.recommendation}</p></div><button onClick={() => onLog({ id: Date.now(), building: 'Canteen', type: 'Waste', title: 'Bin approaching overflow capacity', detail: `Computer vision estimate: ${result.percent}% full, high overflow risk detected.`, recommendation: result.recommendation, severity: 'high', time: 'Just now', status: 'Open' })} className="self-end rounded-xl bg-amber-600 px-4 py-2.5 text-sm font-semibold text-white shadow-sm transition hover:bg-amber-700">Log this issue</button></div></div>}</div>;
}

function Issues({ issues, onResolve }: { issues: Issue[]; onResolve: (id: number) => void }) {
  const [filter, setFilter] = useState('All'); const [search, setSearch] = useState(''); const [expanded, setExpanded] = useState<number | null>(null);
  const filtered = issues.filter((issue) => (filter === 'All' || issue.type === filter || issue.severity === filter.toLowerCase()) && `${issue.title} ${issue.building}`.toLowerCase().includes(search.toLowerCase()));
  return <div className="space-y-6"><SectionTitle eyebrow="Operations center" title="Issues & alerts" detail="Prioritize, assign, and close the loop on campus conditions." action={<div className="hidden items-center gap-2 rounded-xl border bg-card px-3 py-2 text-xs text-muted-foreground sm:flex"><Activity className="h-3.5 w-3.5 text-emerald-500" />Monitoring live</div>} /><div className="flex flex-col gap-3 rounded-2xl border bg-card p-4 shadow-sm sm:flex-row sm:items-center sm:justify-between"><div className="relative flex-1 sm:max-w-xs"><Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" /><input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Search issues…" className="h-10 w-full rounded-lg border bg-background pl-9 pr-3 text-sm outline-none transition focus:border-primary focus:ring-2 focus:ring-primary/20" /></div><div className="flex gap-1 overflow-x-auto rounded-lg bg-muted p-1">{['All', 'Energy', 'Water', 'Waste', 'HVAC'].map((item) => <button key={item} onClick={() => setFilter(item)} className={`whitespace-nowrap rounded-md px-3 py-1.5 text-xs font-semibold transition ${filter === item ? 'bg-card shadow-sm' : 'text-muted-foreground'}`}>{item}</button>)}</div></div><div className="overflow-hidden rounded-2xl border bg-card shadow-sm"><div className="hidden grid-cols-[1fr_150px_100px_100px_30px] gap-4 border-b bg-muted/30 px-5 py-3 text-[10px] font-bold uppercase tracking-wider text-muted-foreground md:grid"><span>Issue</span><span>Type</span><span>Severity</span><span>Status</span><span /></div>{filtered.map((issue) => <div key={issue.id} className="border-b last:border-0"><button onClick={() => setExpanded(expanded === issue.id ? null : issue.id)} className="grid w-full gap-3 px-5 py-4 text-left transition hover:bg-muted/30 md:grid-cols-[1fr_150px_100px_100px_30px] md:items-center md:gap-4"><div className="flex items-start gap-3"><div className={`mt-1.5 h-2 w-2 shrink-0 rounded-full ${issue.status === 'Resolved' ? 'bg-emerald-500' : issue.severity === 'high' ? 'bg-red-500' : issue.severity === 'medium' ? 'bg-amber-500' : 'bg-sky-500'}`} /><div><p className="text-sm font-semibold">{issue.title}</p><p className="mt-1 text-xs text-muted-foreground">{issue.building} · {issue.time}</p></div></div><span className="text-xs font-medium text-muted-foreground">{issue.type}</span><span className={`w-fit rounded-full px-2 py-1 text-[10px] font-bold uppercase ${issue.severity === 'high' ? 'bg-red-100 text-red-700 dark:bg-red-500/15 dark:text-red-400' : issue.severity === 'medium' ? 'bg-amber-100 text-amber-700 dark:bg-amber-500/15 dark:text-amber-400' : 'bg-sky-100 text-sky-700 dark:bg-sky-500/15 dark:text-sky-400'}`}>{issue.severity}</span><span className={`w-fit rounded-full px-2 py-1 text-[10px] font-bold ${issue.status === 'Resolved' ? 'bg-emerald-100 text-emerald-700 dark:bg-emerald-500/15 dark:text-emerald-400' : 'bg-muted text-muted-foreground'}`}>{issue.status}</span><ChevronRight className={`hidden h-4 w-4 text-muted-foreground transition-transform md:block ${expanded === issue.id ? 'rotate-90' : ''}`} /></button>{expanded === issue.id && <div className="animate-fade-in-up bg-muted/20 px-5 pb-4 pl-10"><p className="max-w-3xl text-sm leading-relaxed text-muted-foreground">{issue.detail}</p><div className="mt-3 flex flex-col gap-3 rounded-xl border bg-card p-4 sm:flex-row sm:items-start sm:justify-between"><div><p className="text-[10px] font-bold uppercase tracking-wider text-primary">Recommended action</p><p className="mt-1 text-sm">{issue.recommendation}</p></div>{issue.status === 'Open' && <button onClick={() => onResolve(issue.id)} className="shrink-0 rounded-lg bg-primary px-3 py-2 text-xs font-bold text-primary-foreground hover:bg-primary/90">Mark resolved</button>}</div></div>}</div>)}{filtered.length === 0 && <div className="p-12 text-center text-sm text-muted-foreground"><Search className="mx-auto mb-3 h-7 w-7" />No issues match your filters.</div>}</div></div>;
}

function Reports({ buildings, issues }: { buildings: Building[]; issues: Issue[] }) {
  const [report, setReport] = useState(false); const openIssues = issues.filter((issue) => issue.status === 'Open');
  const leaderboard = [...buildings].sort((a, b) => b.score - a.score);
  return <div className="space-y-6"><SectionTitle eyebrow="Decision support" title="Analytics & reports" detail="See the trends behind your campus sustainability score." action={<button onClick={() => setReport(true)} className="flex items-center gap-2 rounded-xl bg-primary px-4 py-2.5 text-sm font-semibold text-primary-foreground shadow-sm transition hover:bg-primary/90"><Sparkles className="h-4 w-4" />Generate AI report</button>} /><div className="grid gap-6 lg:grid-cols-[minmax(0,1.35fr)_minmax(280px,0.65fr)]"><div className="rounded-2xl border bg-card p-5 shadow-sm"><div className="flex items-center justify-between"><div><h2 className="font-display text-lg font-bold">Resource trends</h2><p className="mt-1 text-xs text-muted-foreground">Campus-wide performance · last 7 days</p></div><span className="rounded-lg bg-emerald-50 px-2.5 py-1.5 text-xs font-semibold text-emerald-700 dark:bg-emerald-500/15 dark:text-emerald-400">↓ 12.6% impact</span></div><div className="mt-6 h-[300px]"><ResponsiveContainer width="100%" height="100%"><AreaChart data={trendData}><defs><linearGradient id="energyFill" x1="0" y1="0" x2="0" y2="1"><stop offset="5%" stopColor="#0ea5e9" stopOpacity={0.25} /><stop offset="95%" stopColor="#0ea5e9" stopOpacity={0} /></linearGradient><linearGradient id="waterFill" x1="0" y1="0" x2="0" y2="1"><stop offset="5%" stopColor="#10b981" stopOpacity={0.22} /><stop offset="95%" stopColor="#10b981" stopOpacity={0} /></linearGradient></defs><CartesianGrid strokeDasharray="3 3" stroke="hsl(var(--border))" vertical={false} /><XAxis dataKey="day" tick={{ fontSize: 11 }} tickLine={false} axisLine={false} /><YAxis tick={{ fontSize: 11 }} tickLine={false} axisLine={false} /><Tooltip contentStyle={{ borderRadius: 12, border: '1px solid hsl(var(--border))', background: 'hsl(var(--card))', fontSize: 12 }} /><Area type="monotone" dataKey="energy" name="Energy (kWh)" stroke="#0ea5e9" fill="url(#energyFill)" strokeWidth={2.5} /><Area type="monotone" dataKey="water" name="Water (L)" stroke="#10b981" fill="url(#waterFill)" strokeWidth={2.5} /></AreaChart></ResponsiveContainer></div></div><div className="rounded-2xl border bg-card p-5 shadow-sm"><h2 className="font-display text-lg font-bold">Impact mix</h2><p className="mt-1 text-xs text-muted-foreground">Where opportunities are found</p><div className="mt-4 h-[180px]"><ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={[{ name: 'Energy', value: 42, color: '#0ea5e9' }, { name: 'Water', value: 31, color: '#10b981' }, { name: 'Waste', value: 17, color: '#f59e0b' }, { name: 'HVAC', value: 10, color: '#8b5cf6' }]} dataKey="value" innerRadius={54} outerRadius={76} paddingAngle={3}>{[{ color: '#0ea5e9' }, { color: '#10b981' }, { color: '#f59e0b' }, { color: '#8b5cf6' }].map((entry, index) => <Cell key={index} fill={entry.color} />)}</Pie><Tooltip contentStyle={{ borderRadius: 12, border: '1px solid hsl(var(--border))', background: 'hsl(var(--card))', fontSize: 12 }} /></PieChart></ResponsiveContainer></div><div className="grid grid-cols-2 gap-2">{[['Energy', '#0ea5e9'], ['Water', '#10b981'], ['Waste', '#f59e0b'], ['HVAC', '#8b5cf6']].map(([label, color]) => <span key={label} className="flex items-center gap-2 text-xs text-muted-foreground"><span className="h-2 w-2 rounded-full" style={{ backgroundColor: color }} />{label}</span>)}</div></div></div><div className="rounded-2xl border bg-card p-5 shadow-sm"><div className="flex items-center justify-between"><div><h2 className="font-display text-lg font-bold">Building leaderboard</h2><p className="mt-1 text-xs text-muted-foreground">Sustainability score by zone</p></div><Target className="h-5 w-5 text-primary" /></div><div className="mt-6 h-[250px]"><ResponsiveContainer width="100%" height="100%"><BarChart data={leaderboard} layout="vertical" margin={{ left: 8, right: 16 }}><XAxis type="number" domain={[0, 100]} hide /><YAxis type="category" dataKey="short" width={76} tick={{ fontSize: 11 }} tickLine={false} axisLine={false} /><Bar dataKey="score" radius={[0, 6, 6, 0]}>{leaderboard.map((building) => <Cell key={building.id} fill={building.status === 'critical' ? '#ef4444' : building.status === 'warning' ? '#f59e0b' : '#10b981'} />)}</Bar></BarChart></ResponsiveContainer></div></div>{report && <div className="animate-fade-in-up rounded-2xl border border-primary/20 bg-primary/[0.03] p-6 shadow-sm"><div className="flex items-start justify-between gap-4"><div><div className="flex items-center gap-2 text-primary"><Sparkles className="h-4 w-4" /><span className="text-[11px] font-bold uppercase tracking-[0.18em]">AI-generated report</span></div><h2 className="mt-3 font-display text-2xl font-bold">Campus sustainability brief</h2><p className="mt-1 text-xs text-muted-foreground">Generated just now · Based on live campus data</p></div><button onClick={() => setReport(false)} className="rounded-lg p-2 text-muted-foreground hover:bg-muted"><X className="h-4 w-4" /></button></div><div className="mt-6 grid gap-4 sm:grid-cols-3"><div className="rounded-xl border bg-card p-4"><p className="text-xs text-muted-foreground">Open findings</p><p className="mt-1 text-2xl font-bold">{openIssues.length}</p></div><div className="rounded-xl border bg-card p-4"><p className="text-xs text-muted-foreground">Savings potential</p><p className="mt-1 text-2xl font-bold text-emerald-600">18.4%</p></div><div className="rounded-xl border bg-card p-4"><p className="text-xs text-muted-foreground">Campus score</p><p className="mt-1 text-2xl font-bold text-primary">78 / 100</p></div></div><div className="mt-6 grid gap-6 border-t pt-5 md:grid-cols-2"><div><h3 className="font-display font-bold">Executive summary</h3><p className="mt-2 text-sm leading-relaxed text-muted-foreground">EcoCampus AI detected strong efficiency gains in the Library and Sports Complex. The highest-impact opportunity is Girls Hostel Block B, where overnight water flow with zero occupancy indicates a likely plumbing leak.</p></div><div><h3 className="font-display font-bold">Priority actions</h3><ul className="mt-2 space-y-2 text-sm text-muted-foreground"><li className="flex gap-2"><span className="text-primary">01</span> Inspect Hostel B basement plumbing within 24 hours.</li><li className="flex gap-2"><span className="text-primary">02</span> Schedule Canteen collection before evening peak.</li><li className="flex gap-2"><span className="text-primary">03</span> Expand occupancy-based HVAC scheduling.</li></ul></div></div><button className="mt-6 flex items-center gap-2 rounded-xl border bg-card px-4 py-2.5 text-sm font-semibold transition hover:border-primary hover:text-primary"><FileText className="h-4 w-4" />Download as PDF</button></div>}</div>;
}

function Assistant({ buildings, issues }: { buildings: Building[]; issues: Issue[] }) {
  const [messages, setMessages] = useState([{ role: 'assistant', text: 'Hi Alex. I’m your campus sustainability copilot. Ask me about resource usage, urgent issues, or ways to improve your score.' }]); const [input, setInput] = useState(''); const [typing, setTyping] = useState(false);
  const ask = (question: string) => { if (!question.trim()) return; setMessages((current) => [...current, { role: 'user', text: question }]); setInput(''); setTyping(true); window.setTimeout(() => { const critical = buildings.find((building) => building.status === 'critical'); setMessages((current) => [...current, { role: 'assistant', text: question.toLowerCase().includes('water') ? `The biggest water opportunity is ${critical?.name ?? 'Hostel Block B'}. It is using 48.2 L/min with zero occupancy, which is a strong leak signal. Fixing it could save roughly 1,200 liters per day.` : question.toLowerCase().includes('score') ? 'Your campus score is 78/100. The fastest lift would come from resolving the Hostel B water anomaly and replicating the Library’s lighting schedule in the Academic Block.' : `I found ${issues.filter((issue) => issue.status === 'Open').length} open issues. The most urgent is the overnight water flow at Girls Hostel Block B. Would you like a prioritized action plan?` }]); setTyping(false); }, 900); };
  return <div className="mx-auto flex max-w-4xl flex-col space-y-6"><SectionTitle eyebrow="Your sustainability copilot" title="Ask EcoCampus" detail="Get clear answers grounded in your campus data." /><div className="flex min-h-[560px] flex-col overflow-hidden rounded-2xl border bg-card shadow-sm"><div className="flex items-center gap-3 border-b bg-muted/20 px-5 py-4"><div className="flex h-10 w-10 items-center justify-center rounded-xl bg-primary text-primary-foreground"><Bot className="h-5 w-5" /></div><div><p className="font-display font-bold">EcoCampus assistant</p><p className="flex items-center gap-1.5 text-xs text-muted-foreground"><span className="h-1.5 w-1.5 rounded-full bg-emerald-500" />Online · Grounded in live data</p></div></div><div className="flex-1 space-y-5 overflow-y-auto p-5 scrollbar-thin">{messages.map((message, index) => <div key={index} className={`flex gap-3 ${message.role === 'user' ? 'justify-end' : ''}`}><div className={`max-w-[82%] rounded-2xl px-4 py-3 text-sm leading-relaxed ${message.role === 'user' ? 'rounded-br-md bg-primary text-primary-foreground' : 'rounded-bl-md bg-muted'}`}>{message.text}</div></div>)}{typing && <div className="flex gap-1 rounded-2xl rounded-bl-md bg-muted px-4 py-3 w-fit"><span className="h-1.5 w-1.5 animate-bounce rounded-full bg-muted-foreground" /><span className="h-1.5 w-1.5 animate-bounce rounded-full bg-muted-foreground [animation-delay:120ms]" /><span className="h-1.5 w-1.5 animate-bounce rounded-full bg-muted-foreground [animation-delay:240ms]" /></div>}</div><div className="border-t p-4"><div className="mb-3 flex flex-wrap gap-2">{['Which building needs urgent attention?', 'How can we save more water?', 'What is our current score?'].map((question) => <button key={question} onClick={() => ask(question)} className="rounded-full border px-3 py-1.5 text-xs font-medium text-muted-foreground transition hover:border-primary hover:text-primary">{question}</button>)}</div><div className="flex gap-2"><input value={input} onChange={(event) => setInput(event.target.value)} onKeyDown={(event) => event.key === 'Enter' && ask(input)} placeholder="Ask about your campus…" className="h-11 flex-1 rounded-xl border bg-background px-4 text-sm outline-none transition focus:border-primary focus:ring-2 focus:ring-primary/20" /><button onClick={() => ask(input)} className="flex h-11 w-11 shrink-0 items-center justify-center rounded-xl bg-primary text-primary-foreground transition hover:bg-primary/90"><Send className="h-4 w-4" /></button></div></div></div></div>;
}

export default function Home() {
  const [view, setView] = useState<View>('dashboard'); const [buildings, setBuildings] = useState(initialBuildings); const [issues, setIssues] = useState(initialIssues); const [selectedBuilding, setSelectedBuilding] = useState<Building | null>(null); const [dark, setDark] = useState(false); const [mobileNav, setMobileNav] = useState(false); const [lastUpdated, setLastUpdated] = useState('just now');
  useEffect(() => { const timer = window.setInterval(() => { setBuildings((current) => current.map((building) => ({ ...building, energy: Math.max(30, building.energy + Math.round((Math.random() - 0.5) * 10)), water: Math.max(3, Number((building.water + (Math.random() - 0.5) * 1.6).toFixed(1)))}))); setLastUpdated('just now'); }, 7000); return () => window.clearInterval(timer); }, []);
  useEffect(() => { document.documentElement.classList.toggle('dark', dark); }, [dark]);
  const openIssues = useMemo(() => issues.filter((issue) => issue.status === 'Open').length, [issues]);
  const resolveIssue = (id: number) => setIssues((current) => current.map((issue) => issue.id === id ? { ...issue, status: 'Resolved' } : issue));
  const navigate = (next: View) => { setView(next); setSelectedBuilding(null); setMobileNav(false); };
  const selectBuilding = (building: Building) => { setSelectedBuilding(building); setView('map'); };
  const logIssue = (issue: Issue) => { setIssues((current) => [issue, ...current]); setView('issues'); };
  const currentLabel = navItems.find((item) => item.id === view)?.label ?? 'Overview';
  return <div className="min-h-screen bg-background"><aside className={`fixed inset-y-0 left-0 z-40 flex w-[248px] flex-col border-r bg-card transition-transform duration-300 ${mobileNav ? 'translate-x-0' : '-translate-x-full'} lg:translate-x-0`}><div className="flex h-[76px] items-center gap-3 border-b px-6"><div className="flex h-9 w-9 items-center justify-center rounded-xl bg-primary text-primary-foreground shadow-sm"><Leaf className="h-5 w-5" /></div><div><p className="font-display text-[15px] font-bold tracking-tight">EcoCampus <span className="text-primary">AI</span></p><p className="text-[10px] font-medium uppercase tracking-[0.15em] text-muted-foreground">Campus intelligence</p></div><button onClick={() => setMobileNav(false)} className="ml-auto rounded-lg p-1.5 text-muted-foreground hover:bg-muted lg:hidden"><X className="h-4 w-4" /></button></div><div className="flex-1 px-3 py-6"><p className="mb-3 px-3 text-[10px] font-bold uppercase tracking-[0.18em] text-muted-foreground">Workspace</p><nav className="space-y-1">{navItems.map(({ id, label, icon: Icon }) => <button key={id} onClick={() => navigate(id)} className={`group flex w-full items-center gap-3 rounded-xl px-3 py-2.5 text-sm font-medium transition ${view === id && !selectedBuilding ? 'bg-primary/10 text-primary' : 'text-muted-foreground hover:bg-muted hover:text-foreground'}`}><Icon className={`h-[18px] w-[18px] ${view === id && !selectedBuilding ? 'text-primary' : ''}`} /><span>{label}</span>{id === 'issues' && openIssues > 0 && <span className="ml-auto rounded-full bg-red-100 px-1.5 py-0.5 text-[10px] font-bold text-red-600 dark:bg-red-500/15 dark:text-red-400">{openIssues}</span>}</button>)}</nav><p className="mb-3 mt-8 px-3 text-[10px] font-bold uppercase tracking-[0.18em] text-muted-foreground">System</p><nav className="space-y-1"><button className="flex w-full items-center gap-3 rounded-xl px-3 py-2.5 text-sm font-medium text-muted-foreground transition hover:bg-muted hover:text-foreground"><Settings className="h-[18px] w-[18px]" />Settings</button><button className="flex w-full items-center gap-3 rounded-xl px-3 py-2.5 text-sm font-medium text-muted-foreground transition hover:bg-muted hover:text-foreground"><CircleHelp className="h-[18px] w-[18px]" />Help center</button></nav></div><div className="m-3 rounded-2xl bg-gradient-to-br from-primary/10 to-sky-500/10 p-4"><div className="flex items-center gap-2"><Sparkles className="h-4 w-4 text-primary" /><span className="text-xs font-bold">Pro tip</span></div><p className="mt-2 text-xs leading-relaxed text-muted-foreground">Resolve Hostel B’s water anomaly to improve your score by up to 6 points.</p></div><div className="flex items-center gap-3 border-t p-4"><div className="flex h-9 w-9 items-center justify-center rounded-full bg-sky-100 text-xs font-bold text-sky-700 dark:bg-sky-500/15 dark:text-sky-400">AM</div><div className="min-w-0 flex-1"><p className="truncate text-sm font-semibold">Alex Morgan</p><p className="truncate text-[11px] text-muted-foreground">Sustainability admin</p></div><MoreHorizontal className="h-4 w-4 text-muted-foreground" /></div></aside><div className="lg:pl-[248px]"><header className="sticky top-0 z-30 flex h-[76px] items-center justify-between border-b bg-background/90 px-4 backdrop-blur-md sm:px-8"><div className="flex items-center gap-3"><button onClick={() => setMobileNav(true)} className="rounded-lg p-2 text-muted-foreground hover:bg-muted lg:hidden"><Menu className="h-5 w-5" /></button><div><p className="text-xs text-muted-foreground">Workspace / <span className="font-medium text-foreground">{currentLabel}</span></p><p className="mt-0.5 text-[11px] text-muted-foreground"><span className="mr-1.5 inline-block h-1.5 w-1.5 rounded-full bg-emerald-500" />Live data · Updated {lastUpdated}</p></div></div><div className="flex items-center gap-2"><button onClick={() => setDark(!dark)} className="flex h-9 w-9 items-center justify-center rounded-xl border bg-card text-muted-foreground transition hover:border-primary hover:text-primary">{dark ? <Sun className="h-4 w-4" /> : <Moon className="h-4 w-4" />}</button><button onClick={() => navigate('issues')} className="relative flex h-9 w-9 items-center justify-center rounded-xl border bg-card text-muted-foreground transition hover:border-primary hover:text-primary"><Bell className="h-4 w-4" />{openIssues > 0 && <span className="absolute right-1 top-1 h-1.5 w-1.5 rounded-full bg-red-500" />}</button><div className="ml-1 hidden h-8 w-px bg-border sm:block" /><div className="hidden items-center gap-2 sm:flex"><div className="flex h-8 w-8 items-center justify-center rounded-full bg-sky-100 text-[10px] font-bold text-sky-700 dark:bg-sky-500/15 dark:text-sky-400">AM</div><span className="text-xs font-semibold">Alex Morgan</span></div></div></header><main className="mx-auto max-w-[1600px] p-4 sm:p-8">{selectedBuilding ? <BuildingDetail building={selectedBuilding} issues={issues} onBack={() => setSelectedBuilding(null)} onScan={() => { setSelectedBuilding(null); setView('scanner'); }} /> : view === 'dashboard' ? <Dashboard buildings={buildings} issues={issues} onResolve={resolveIssue} onSelect={selectBuilding} /> : view === 'map' ? <div className="space-y-6"><SectionTitle eyebrow="Live digital twin" title="Campus map" detail="Explore every monitored zone and inspect its current health." /><CampusMap buildings={buildings} onSelect={selectBuilding} /><div className="flex flex-wrap gap-4 text-xs text-muted-foreground"><span className="flex items-center gap-2"><span className="h-2 w-2 rounded-full bg-emerald-500" />Good condition</span><span className="flex items-center gap-2"><span className="h-2 w-2 rounded-full bg-amber-500" />Needs attention</span><span className="flex items-center gap-2"><span className="h-2 w-2 rounded-full bg-red-500" />Critical anomaly</span></div></div> : view === 'scanner' ? <Scanner onLog={logIssue} /> : view === 'issues' ? <Issues issues={issues} onResolve={resolveIssue} /> : view === 'reports' ? <Reports buildings={buildings} issues={issues} /> : <Assistant buildings={buildings} issues={issues} />}</main></div></div>;
}
